namespace ghidra.app.plugin.core.decompile.actions;

using static ghidra.app.plugin.core.decompile.actions.PCodeCfgGraphTask.PcodeGraphSubType;



using ghidra.app.plugin.core.decompile.actions.PCodeCfgGraphTask;
using ghidra.app.plugin.core.graph;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.pcode;
using ghidra.program.model.pcode;
using ghidra.service.graph;
using ghidra.util.exception;

/**
 * Listener for when an AST graph's nodes are selected.
 */
public class PCodeCfgDisplayListener : AddressBasedGraphDisplayListener {
	private HighFunction hfunction;
	private PcodeGraphSubType graphType;

	PCodeCfgDisplayListener(PluginTool tool, GraphDisplay display, HighFunction hfunction,
			PcodeGraphSubType graphType) : base(tool, hfunction.getFunction().getProgram(), display)
    {
		this.hfunction = hfunction;
		this.graphType = graphType;
	}

	/* @Override */
	protected Set<AttributedVertex> getVertices(AddressSetView selection) {
		if (graphType != CONTROL_FLOW_GRAPH) {
			return null;
		}
		Set<AttributedVertex> vertices = new();
		List<PcodeBlockBasic> blocks = hfunction.getBasicBlocks();
		foreach (PcodeBlockBasic block in blocks) {
			Address start = block.getStart();
			Address stop = block.getStop();
			if (selection.intersects(start, stop)) {
				string id = Integer.toString(block.getIndex());
				AttributedVertex vertex = graphDisplay.getGraph().getVertex(id);
				if (vertex != null) {
					vertices.add(vertex);
				}
			}
		}
		return vertices;
	}

	/* @Override */
	protected AddressSet getAddresses(Set<AttributedVertex> vertices) {
		if (graphType != CONTROL_FLOW_GRAPH) {
			return null;
		}

		AddressSet set = new AddressSet();
		List<PcodeBlockBasic> blocks = hfunction.getBasicBlocks();
		foreach (AttributedVertex vertex in vertices) {
			try {
				int index = Integer.parseInt(vertex.getId());
				PcodeBlockBasic block = blocks.get(index);
				Address start = block.getStart();
				set.addRange(start, block.getStop());
			}
			catch (NumberFormatException e) {
				// continue
			}
		}
		return set;
	}

	/* @Override */
	protected string getVertexId(Address address) {
		if (graphType != CONTROL_FLOW_GRAPH) {
			return null;
		}
		List<PcodeBlockBasic> blocks = hfunction.getBasicBlocks();
		foreach (PcodeBlockBasic block in blocks) {
			Address start = block.getStart();
			Address stop = block.getStop();
			if (address.compareTo(start) >= 0 && address.compareTo(stop) <= 0) {
				return Integer.toString(block.getIndex());
			}
		}
		return base.getVertexId(address);
	}

	/* @Override */
	protected Address getAddress(AttributedVertex vertex) {
		List<PcodeBlockBasic> blocks = hfunction.getBasicBlocks();

		try {
			int index = Integer.parseInt(vertex.getId());
			PcodeBlockBasic block = blocks.get(index);
			return block.getStart();
		}
		catch (NumberFormatException e) {
			throw new AssertException("Bad vertex id, expected a number but got " + vertex.getId());
		}
	}

	/* @Override */
	public GraphDisplayListener cloneWith(GraphDisplay display) {
		return new PCodeCfgDisplayListener(tool, graphDisplay, hfunction, graphType);
	}

}
